import{_ as o,a0 as p,w as r,s as d,ao as n,I as a,x as e,a1 as t,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何編譯 Linux 內核 | LCTT x X-CMD","titleTemplate":false,"description":"如何編譯 Linux 內核 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何編譯 Linux 內核 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何編譯 Linux 內核 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180427 How to Compile a Linux Kernel","title":"如何編譯 Linux 內核","tag":"201805","desc":""},"relativePath":"201805/20180427 How to Compile a Linux Kernel.md","filePath":"[post].md"}'),u={name:"201805/20180427 How to Compile a Linux Kernel.md"};function h(g,i,k,b,c,m){const s=p("Link");return r(),d("div",null,[i[23]||(i[23]=n('<h1 id="如何編譯-linux-內核" tabindex="-1">如何編譯 Linux 內核 <a class="header-anchor" href="#如何編譯-linux-內核" aria-label="Permalink to “如何編譯 Linux 內核”">​</a></h1><blockquote><p>Jack 將帶你在 Ubuntu 16.04 服務器上走過內核編譯之旅。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/chester-alvarez-644-unsplash.jpg?itok=aFxG9kUZ" alt=""></p><p>曾經有一段時間，升級 Linux 內核讓很多用户打心裏有所畏懼。在那個時候，升級內核包含了很多步驟，也需要很多時間。現在，內核的安裝可以輕易地通過像 <code>apt</code> 這樣的包管理器來處理。通過添加特定的倉庫，你能很輕易地安裝實驗版本的或者指定版本的內核（比如針對音頻產品的實時內核）。</p><p>考慮一下，既然升級內核如此容易，為什麼你不願意自行編譯一個呢？這裏列舉一些可能的原因：</p><ul><li>你想要簡單瞭解編譯內核的過程</li><li>你需要啓用或者禁用內核中特定的選項，因為它們沒有出現在標準選項裏</li><li>你想要啓用標準內核中可能沒有添加的硬件支持</li><li>你使用的發行版需要你編譯內核</li><li>你是一個學生，而編譯內核是你的任務</li></ul><p>不管出於什麼原因，懂得如何編譯內核是非常有用的，而且可以被視作一個通行權。當我第一次編譯一個新的 Linux 內核（那是很久以前了），然後嘗試從它啓動，我從中（系統馬上就崩潰了，然後不斷地嘗試和失敗）感受到一種特定的興奮。</p><p>既然這樣，讓我們來實驗一下編譯內核的過程。我將使用 Ubuntu 16.04 Server 來進行演示。在運行了一次常規的 <code>sudo apt upgrade</code> 之後，當前安裝的內核版本是 <code>4.4.0-121</code>。我想要升級內核版本到 <code>4.17</code>， 讓我們小心地開始吧。</p><p>有一個警告：強烈建議你在虛擬機裏實驗這個過程。基於虛擬機，你總能創建一個快照，然後輕鬆地從任何問題中回退出來。不要在產品機器上使用這種方式升級內核，除非你知道你在做什麼。</p><h3 id="下載內核" tabindex="-1">下載內核 <a class="header-anchor" href="#下載內核" aria-label="Permalink to “下載內核”">​</a></h3>',10)),a("p",null,[i[1]||(i[1]=e("我們要做的第一件事是下載內核源碼。在 ",-1)),t(s,{href:"https://www.kernel.org/"},{default:l(()=>[...i[0]||(i[0]=[e("Kernel.org",-1)])]),_:1}),i[2]||(i[2]=e(" 找到你要下載的所需內核的 URL。找到 URL 之後，使用如下命令（我以 ",-1)),i[3]||(i[3]=a("code",null,"4.17 RC2",-1)),i[4]||(i[4]=e(" 內核為例） 來下載源碼文件:",-1))]),i[24]||(i[24]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://git.kernel.org/torvalds/t/linux-4.17-rc2.tar.gz</span></span></code></pre></div><p>在下載期間，有一些事需要去考慮。</p><h3 id="安裝需要的環境" tabindex="-1">安裝需要的環境 <a class="header-anchor" href="#安裝需要的環境" aria-label="Permalink to “安裝需要的環境”">​</a></h3><p>為了編譯內核，我們首先得安裝一些需要的環境。這可以通過一個命令來完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install git fakeroot build-essential ncurses-dev xz-utils libssl-dev bc flex libelf-dev bison</span></span></code></pre></div><p>務必注意：你將需要至少 128GB 的本地可用磁盤空間來完成內核的編譯過程。因此你必須確保有足夠的空間。</p><h3 id="解壓源碼" tabindex="-1">解壓源碼 <a class="header-anchor" href="#解壓源碼" aria-label="Permalink to “解壓源碼”">​</a></h3><p>在新下載的內核所在的文件夾下，使用該命令來解壓內核：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tar xvzf linux-4.17-rc2.tar.gz</span></span></code></pre></div><p>使用命令 <code>cd linux-4.17-rc2</code> 進入新生成的文件夾。</p><h3 id="配置內核" tabindex="-1">配置內核 <a class="header-anchor" href="#配置內核" aria-label="Permalink to “配置內核”">​</a></h3><p>在正式編譯內核之前，我們首先必須配置需要包含哪些模組。實際上，有一些非常簡單的方式來配置。使用一個命令，你能拷貝當前內核的配置文件，然後使用可靠的 <code>menuconfig</code> 命令來做任何必要的更改。使用如下命令來完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp /boot/config-$(uname -r) .config</span></span></code></pre></div><p>現在你有一個配置文件了，輸入命令 <code>make menuconfig</code>。該命令將打開一個配置工具（圖 1），它可以讓你遍歷每個可用模組，然後啓用或者禁用你需要或者不需要的模組。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kernel_compile_1.jpg?itok=ZNybYgEt" alt="menuconfig" title="menuconfig"></p><p><em>圖 1: 運行中的 <code>make menuconfig</code></em></p><p>很有可能你會禁用掉內核中的一個重要部分，所以在 <code>menuconfig</code> 期間小心地一步步進行。如果你對某個選項不確定，不要去管它。或者更好的方法是使用我們拷貝的當前運行的內核的配置文件（因為我們知道它可以工作）。一旦你已經遍歷了整個配置列表（它非常長），你就準備好開始編譯了。</p><h3 id="編譯和安裝" tabindex="-1">編譯和安裝 <a class="header-anchor" href="#編譯和安裝" aria-label="Permalink to “編譯和安裝”">​</a></h3><p>現在是時候去實際地編譯內核了。第一步是使用 <code>make</code> 命令去編譯。調用 <code>make</code> 命令然後回答必要的問題（圖 2）。這些問題取決於你將升級的現有內核以及升級後的內核。相信我，將會有非常多的問題要回答，因此你得預留大量的時間。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/kernel_compile_2.jpg?itok=TYfV02wC" alt="make" title="make"></p><p><em>圖 2: 回答 <code>make</code> 命令的問題</em></p><p>回答了長篇累牘的問題之後，你就可以用如下的命令安裝那些之前啓用的模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>make modules_install</span></span></code></pre></div><p>又來了，這個命令將耗費一些時間，所以要麼坐下來看着編譯輸出，或者去做些其他事（因為編譯期間不需要你的輸入）。可能的情況是，你想要去進行別的任務（除非你真的喜歡看着終端界面上飛舞而過的輸出）。</p><p>現在我們使用這個命令來安裝內核：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo make install</span></span></code></pre></div><p>又一次，另一個將要耗費大量可觀時間的命令。事實上，<code>make install</code> 命令將比 <code>make modules_install</code> 命令花費更多的時間。去享用午餐，配置一個路由器，將 Linux 安裝在一些服務器上，或者小睡一會吧。</p><h3 id="啓用內核作為引導" tabindex="-1">啓用內核作為引導 <a class="header-anchor" href="#啓用內核作為引導" aria-label="Permalink to “啓用內核作為引導”">​</a></h3><p>一旦 <code>make install</code> 命令完成了，就是時候將內核啓用來作為引導。使用這個命令來實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo update-initramfs -c -k 4.17-rc2</span></span></code></pre></div><p>當然，你需要將上述內核版本號替換成你編譯完的。當命令執行完畢後，使用如下命令來更新 grub：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo update-grub</span></span></code></pre></div><p>現在你可以重啓系統並且選擇新安裝的內核了。</p><h3 id="恭喜" tabindex="-1">恭喜! <a class="header-anchor" href="#恭喜" aria-label="Permalink to “恭喜!”">​</a></h3><p>你已經編譯了一個 Linux 內核！它是一項耗費時間的活動；但是，最終你的 Linux 發行版將擁有一個定製的內核，同時你也將擁有一項被許多 Linux 管理員所傾向忽視的重要技能。</p>',35)),a("p",null,[i[6]||(i[6]=e("從 Linux 基金會和 edX 提供的免費 ",-1)),t(s,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:l(()=>[...i[5]||(i[5]=[e("“Introduction to Linux”",-1)])]),_:1}),i[7]||(i[7]=e(" 課程來學習更多的 Linux 知識。",-1))]),i[25]||(i[25]=a("hr",null,null,-1)),a("p",null,[i[9]||(i[9]=e("via: ",-1)),t(s,{href:"https://www.linux.com/learn/intro-to-linux/2018/4/how-compile-linux-kernel-0"},{default:l(()=>[...i[8]||(i[8]=[e("https://www.linux.com/learn/intro-to-linux/2018/4/how-compile-linux-kernel-0",-1)])]),_:1})]),a("p",null,[i[14]||(i[14]=e("作者：",-1)),t(s,{href:"https://www.linux.com/users/jlwallen"},{default:l(()=>[...i[10]||(i[10]=[e("Jack Wallen",-1)])]),_:1}),i[15]||(i[15]=e(" 選題：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[11]||(i[11]=[e("lujun9972",-1)])]),_:1}),i[16]||(i[16]=e(" 譯者：",-1)),t(s,{href:"https://github.com/icecoobe"},{default:l(()=>[...i[12]||(i[12]=[e("icecoobe",-1)])]),_:1}),i[17]||(i[17]=e(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...i[13]||(i[13]=[e("wxy",-1)])]),_:1})]),a("p",null,[i[20]||(i[20]=e("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[18]||(i[18]=[e("LCTT",-1)])]),_:1}),i[21]||(i[21]=e(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:l(()=>[...i[19]||(i[19]=[e("Linux中國",-1)])]),_:1}),i[22]||(i[22]=e(" 榮譽推出",-1))])])}const w=o(u,[["render",h]]);export{C as __pageData,w as default};
